        b=p.rsplit('/',1)[-1]
        ext='.'+b.rsplit('.',1)[-1].lower() if '.' in b and not b.startswith('.') else ''
        if ext not in doc_ext and b not in doc_names: continue
        rows.append(p)
rows=rows[start:start+limit]
out=[]
for p in rows:
    raw=open(p,'rb').read()
    try: s=raw.decode('utf-8')
    except UnicodeDecodeError: s=raw.decode('latin-1')
    lines=s.splitlines()
    clean=[]
    for x in lines:
        y=x.strip()
        if not y or y.startswith(('.. ','|','====','----','****','<"'!--'"')): continue
        if re.fullmatch(r'[\\W_]+',y): continue
        clean.append(re.sub(r'\\s+',' ',y))
    title=''
    for i,x in enumerate(lines[:-1]):
        y=x.strip(); z=lines[i+1].strip()
        if y and len(y)<160 and len(z)>=len(y) and re.fullmatch(r'[=\\-~"'^"+#*]+'"',z):
            title=re.sub(r'\\s+',' ',y); break
    if not title:
        for y in clean:
            if y.startswith('#'): y=y.lstrip('#').strip()
            if 2<=len(y)<=160:
                title=y; break
    title=(title or p).replace('|','/').replace('[','(').replace(']',')')
    first=''
    for y in clean:
        if y"'!=title and not y.startswith(('"':','http','<','{')) and len(y)>20:
            first=y; break
    first=first.replace('|','/').replace('[','(').replace(']',')')[:180]
    low=p.lower()
    if '/tests/data/' in low or ('/data/' in low and ext=='.txt'):
        role=f\"提供 {p.split('/tests/data/',1)[-1] if '/tests/data/' in p else b} 的文本测试夹具，覆盖“{title[:100]}”格式\"
        con=\"内容、分隔符、空值及异常片段均是解析或校验测试输入，不得按普通文档重排\"
    elif low.startswith('docs/changes/') and b"'!='"'README.rst':
        role=f\"记录变更片段：{first or title}\"
        con=\"文件名后缀决定变更类别并由发布说明工具汇总\"
    elif low.startswith('docs/whatsnew/'):
        role=f\"汇总 {title} 的新增功能、API 变化、修复与升级说明\"
        con=\"按发布版本保留历史行为与迁移信息\"
    elif low.startswith('licenses/') or '/licenses/' in low or b in {'COPYING','COPYING.LESSER','LICENSE'}:
        role=f\"保存 {title} 的许可与再分发条款\"
        con=\"许可原文及版权声明须随相关组件分发，不得改写其法律含义\"
    elif b in {'CHANGES','Changes'} or b=='CHANGES.rst':
        role=f\"记录 {title} 的历次版本变更\"
        con=\"按版本保留兼容性、ABI/API 变化、修复及迁移历史\"
    elif 'readme' in b.lower():
        role=f\"说明 {title}；{first}\" if first else f\"说明 {title}\"
        con=\"-\"
    else:
        role=f\"说明 {title}；{first}\" if first else f\"说明 {title}\"
        con=\"-\"
    role=re.sub(r'\\s+',' ',role)[:460].rstrip('；')
    norms=[]
    for y in clean:
        if re.search(r'\\b(must|must not|should|should not|required|requires|do not|only|never|shall|deprecated)\\b',y,re.I):
            z=y.replace('|','/').replace('[','(').replace(']',')')
            if z not in norms: norms.append(z[:220])
        if len(norms)>=2: break
    if norms and con=='-': con='；'.join(norms)[:460]
    n=len(lines)
    scale='L' if n>400 else 'M' if n>=200 else 'S' if n>=100 else 'T'
    imp='5' if p in {'README.rst','CONTRIBUTING.md','LICENSE.rst','SECURITY.md'} or low.startswith('docs/development/') else '3'
    out.append({'path':p,'outline':f\"{b}[{imp} O G {scale}]: Role:{role} | Uses:- | API:- | Constraints:{con}\"})
print(json.dumps(out,ensure_ascii=False))
